// ?update@StructureCollapseUpdate@@UAE?AW4UpdateSleepTime@@XZ
// partial score=0.45 date=2026-09-27
// cl: /DNDEBUG /MD /EHsc /D_STLP_USE_STATIC_LIB
// stlport

// BFME retail reconstruction of ?update@StructureCollapseUpdate@@UAE?AW4UpdateSleepTime@@XZ
// (retail 0x002AE950, 944 bytes).  This is the hand-written replacement for the
// __declspec(naked) __emit copy that used to live in
// StructureCollapseUpdateUpdateThunk.cpp.
//
// WHY A SEPARATE TU.  The pristine Zero Hour header lays StructureCollapseUpdate
// out with its interface sub-vtables at object+0x0C and object+0x18, so update()'s
// compiled `this` is object+0x0C and m_collapseState lands at object+0x24.  Retail
// BFME has the UpdateModuleInterface sub-vtable at object+0x10 and DieModuleInterface
// at object+0x20, and the evidence below pins retail's compiled `this` for this
// function to object+0x10:
//
//   * module data   at this-0x0C   (retail +0x000c `mov edi,[esi-0xc]`)
//   * object        at this-0x08   (retail +0x0027 `mov ebx,[esi-8]`)
//   * doPhaseStuff/ this-0x10      (retail +0x0114 `lea ecx,[esi-0x10]`)
//   * m_collapseFrame at this+0x14 (retail +0x0108 `cmp ebp,[esi+0x14]`)
//   * m_burstFrame  at this+0x18
//   * m_collapseState at this+0x1C
//   * m_collapseVelocity at this+0x20
//   * m_currentHeight at this+0x24
//   * cached collapse origin at this+0x28/+0x2C/+0x30
//
// which is exactly the object+0x10 (UpdateModuleInterface vface) convention that the
// already-landed onDie body uses at this-0x1C / this-0x18 / this-0x20.  Declaring
// the view at offset 0 of `this` reproduces retail's `mov esi,ecx` plus a single
// base register, the way StructureCollapseOnDie.cpp does.
//
// Module data, retail offsets (BFME grew the DieMux block): minCollapseDelay +0x34,
// maxCollapseDelay +0x38, minBurstDelay +0x3C, maxBurstDelay +0x40,
// bigBurstFrequency +0x44, collapseDamping +0x48, maxShudder +0x4C.
//
// Retail line numbers are part of the byte match: 192 (WAITING shudder), 228
// (COLLAPSING shudder), 237 (burst pick), 246 (burst interval).  The file pointer is
// RVA 0xCC45E0 = "F:\bfme\Code\gameengine\Source\GameLogic\Object\Update\StructureCollapseUpdate.cpp".

#include <bitset>

typedef int Int;
typedef unsigned int UnsignedInt;
typedef float Real;
typedef bool Bool;

const char *const kRetailSourceFile =
	"F:\\bfme\\Code\\gameengine\\Source\\GameLogic\\Object\\Update\\StructureCollapseUpdate.cpp";

enum UpdateSleepTime
{
	UPDATE_SLEEP_NONE = 0,
	UPDATE_SLEEP_FOREVER = 0x3FFFFFFF
};

enum StructureCollapsePhaseType
{
	SCPHASE_INITIAL = 0,
	SCPHASE_DELAY = 1,
	SCPHASE_BURST = 2,
	// BFME inserted a phase between BURST and FINAL: retail pushes 3 for the
	// "0.7 of the remaining height" tail and 4 for the final burst.
	SCPHASE_ALMOST_FINAL = 3,
	SCPHASE_FINAL = 4
};

class Coord3D
{
public:
	Real x;
	Real y;
	Real z;
};

// WWMatrix3d: twelve reals, translation in the fourth column.
class Matrix3D
{
public:
	Real m00, m01, m02, m03;
	Real m10, m11, m12, m13;
	Real m20, m21, m22, m23;
};

Real GetGameClientRandomValueReal(Real lo, Real hi, char *file, int line);
Int GetGameLogicRandomValue(int lo, int hi, char *file, int line);
Real GetGameLogicRandomValueReal(Real lo, Real hi, char *file, int line);

class GameLogic
{
public:
	// retail reads the frame counter as TheBfmeGameLogic->field_3C, not a call.
	UnsignedInt getFrame() const { return m_frame; }

private:
	char m_unreconstructed00[0x3C];
	UnsignedInt m_frame;
};

extern GameLogic *TheGameLogic;

class GlobalData
{
public:
	Real m_gravity; // retail offset 0x1AC
};

extern GlobalData *TheWritableGlobalData;

class Drawable
{
public:
	void setInstanceMatrix(const Matrix3D *transform, Bool updatePartition);
};

// The retail instance matrix lives at Drawable+0x198 and is the twelve-real
// WWMatrix3d above.
const Matrix3D *getDrawableInstanceMatrix(const Drawable *drawable)
{
	return reinterpret_cast<const Matrix3D *>(
		reinterpret_cast<const char *>(drawable) + 0x198);
}

template <size_t NUMBITS>
class BitFlags
{
public:
	enum BogusInitType
	{
		kInit = 0
	};

	BitFlags(BogusInitType, Int idx1, Int idx2, Int idx3, Int idx4);

private:
	_STL::bitset<NUMBITS> m_bits;
};

typedef BitFlags<304> ModelConditionFlags;

class BodyModuleInterface
{
public:
	virtual void *slot00() { return 0; }
	virtual void *slot01() { return 0; }
	virtual void *slot02() { return 0; }
	virtual void *slot03() { return 0; }
	virtual void *slot04() { return 0; }
	virtual void *slot05() { return 0; }
	virtual void *slot06() { return 0; }
	virtual void *slot07() { return 0; }
	virtual void *slot08() { return 0; }
	virtual void *slot09() { return 0; }
	// retail slot 0x28
	virtual void updateBodyParticleSystems();
};

class Object
{
public:
	void clearModelConditionFlags(const ModelConditionFlags &clear);
	void notifyModelConditionChanged();
};

class Thing
{
public:
	// Object's vtable slot 0x28 is the Drawable getter in BFME.
	virtual void *slot00() { return 0; }
	virtual void *slot01() { return 0; }
	virtual void *slot02() { return 0; }
	virtual void *slot03() { return 0; }
	virtual void *slot04() { return 0; }
	virtual void *slot05() { return 0; }
	virtual void *slot06() { return 0; }
	virtual void *slot07() { return 0; }
	virtual void *slot08() { return 0; }
	virtual void *slot09() { return 0; }
	virtual Drawable *getDrawable() { return m_drawable; }

	void setPosition(const Coord3D *position);
	void setOrientation(Real angle);

	Drawable *m_drawable;
};

class StructureCollapseRetailLayout
{
public:
	Real getCollapseHeight();
};

// The 0x002AE520 body is reached through the ILT at 0x0002DA6F with ZERO pushes
// (retail 0x002AE986: `mov ecx,edi; mov esi,eax; call 0x2DA6F`).  Its 145 bytes
// never read a stack argument, so the `?onDie@StructureToppleUpdate@@UAEXPBVDamageInfo@@@Z`
// name the __emit lift carries is contradicted by its own arity: any clean C++
// reference to a one-argument member pushes four bytes and can never match.  The
// identity is not provable from the body (a NameKeyGenerator static, a lookup keyed
// on [this+8] and a flag byte at [*(this+4)+0xF0]), so the name keeps the address.
//
// STILL MISSING: a symbols.csv row pinning this name at 0x0002DA6F.  A `route=` row is
// REFUSED here -- tools/pin_consistency.py --routes admits a route pin only when the
// image proves the address is an import thunk or a jump stub whose target the ledger
// already names, and 0x0002DA6F jumps to a body the ledger names differently.  So
// 0x002AE520 has to be RE-IDENTIFIED (its own row is a naked __emit lift carrying an
// arity its body contradicts) before any clean C++ can call it with zero pushes.
// tools/one_identity.py will refuse a second name on that address meanwhile.
class Rva002AE520StructureCollapseDone
{
public:
	void collapseDoneLookup();
};

class StructureCollapseUpdateModuleDataView
{
public:
	char m_unreconstructed00[0x34];
	Int m_minCollapseDelay;
	Int m_maxCollapseDelay;
	Int m_minBurstDelay;
	Int m_maxBurstDelay;
	Int m_bigBurstFrequency;
	Real m_collapseDamping;
	Real m_maxShudder;
};

class StructureCollapseObjectView
{
public:
	char m_unreconstructed00[0x38];
	Coord3D m_position;
	Real m_orientation;
	char m_unreconstructed48[0xCC];
	UnsignedInt m_modelConditionFlags;
	char m_unreconstructed114[0xE8];
	BodyModuleInterface *m_bodyModule;
};

// The view of the compiled `this` for this function.  Object+0x10 in retail.
struct StructureCollapseUpdateView
{
	char m_unreconstructed00[0x14];
	UnsignedInt m_collapseFrame;
	UnsignedInt m_burstFrame;
	Int m_collapseState;
	Real m_collapseVelocity;
	Real m_currentHeight;
	Real m_originX;
	Real m_originY;
	Real m_originZ;
};

class StructureCollapseUpdate
{
public:
	virtual UpdateSleepTime update();

protected:
	void doPhaseStuff(StructureCollapsePhaseType scphase, const Coord3D *target);
};

enum StructureCollapseStateType
{
	COLLAPSESTATE_STANDING = 0,
	COLLAPSESTATE_WAITINGFORCOLLAPSESTART = 1,
	COLLAPSESTATE_COLLAPSING = 2,
	COLLAPSESTATE_DONE = 3
};

// BFME's 0x002AE950 body.  The structure is the Zero Hour state machine plus three
// BFME-only steps: the collapse ORIGIN is cached in the module and every shudder is
// applied by setPosition (there is no per-frame setInstanceMatrix in the COLLAPSING
// branch), a 0.7-of-the-remaining-height ALMOST_FINAL phase runs before FINAL, and
// the finished path clears four model conditions through a 304-bit mask.
UpdateSleepTime StructureCollapseUpdate::update(void)
{
	const StructureCollapseUpdateView *self =
		reinterpret_cast<const StructureCollapseUpdateView *>(this);
	StructureCollapseUpdateView *v =
		reinterpret_cast<StructureCollapseUpdateView *>(this);

	// Retail loads the module data into edi BEFORE the STANDING branch resolves:
	// `test eax,eax; push edi; mov edi,[esi-0xc]; jne` (+0006..+000f).  Reading it
	// first, not after the early-out, is what puts the load and the edi save in the
	// fallthrough instead of after the branch.
	const StructureCollapseUpdateModuleDataView *d =
		*reinterpret_cast<const StructureCollapseUpdateModuleDataView *const *>(
			reinterpret_cast<const char *>(this) - 0x0C);

	if (v->m_collapseState == COLLAPSESTATE_STANDING)
		return UPDATE_SLEEP_FOREVER;

	StructureCollapseRetailLayout *base = reinterpret_cast<StructureCollapseRetailLayout *>(
		reinterpret_cast<char *>(this) - 0x10);
	// doPhaseStuff() and getCollapseHeight() share retail's object+0x00 convention.
	StructureCollapseUpdate *module = reinterpret_cast<StructureCollapseUpdate *>(base);

	if (v->m_collapseState == COLLAPSESTATE_WAITINGFORCOLLAPSESTART)
	{
		UnsignedInt now = TheGameLogic->getFrame();
		Thing *building = *reinterpret_cast<Thing *const *>(
			reinterpret_cast<const char *>(this) - 0x08);
		StructureCollapseObjectView *object =
			reinterpret_cast<StructureCollapseObjectView *>(building);

		const Real shudderLimit = d->m_maxShudder;
		Real shudderX = GetGameClientRandomValueReal(-shudderLimit, shudderLimit,
			const_cast<char *>(kRetailSourceFile), 192);
		const Coord3D *currentPosition = &object->m_position;
		Real shudderY = GetGameClientRandomValueReal(-shudderLimit, shudderLimit,
			const_cast<char *>(kRetailSourceFile), 192);

		Drawable *drawable = building->getDrawable();
		Matrix3D instanceMatrix = *getDrawableInstanceMatrix(drawable);
		instanceMatrix.m13 = shudderY;
		instanceMatrix.m03 = shudderX;
		instanceMatrix.m23 = 0.0f;
		drawable->setInstanceMatrix(&instanceMatrix, true);

		if (now >= v->m_collapseFrame)
		{
			v->m_collapseState = COLLAPSESTATE_COLLAPSING;
			module->doPhaseStuff(SCPHASE_BURST, currentPosition);
			// This has to use a game logic random value since the bursts can spawn
			// debris, and debris is sync'd.
			v->m_burstFrame = now + GetGameLogicRandomValue(
				d->m_minBurstDelay, d->m_maxBurstDelay,
				const_cast<char *>(kRetailSourceFile), 206);
		}
	}

	if (v->m_collapseState == COLLAPSESTATE_COLLAPSING)
	{
		UnsignedInt now = TheGameLogic->getFrame();
		Thing *building = *reinterpret_cast<Thing *const *>(
			reinterpret_cast<const char *>(this) - 0x08);
		StructureCollapseObjectView *object =
			reinterpret_cast<StructureCollapseObjectView *>(building);

		v->m_currentHeight -= v->m_collapseVelocity;
		v->m_collapseVelocity -= TheWritableGlobalData->m_gravity * (1.0 - d->m_collapseDamping);

		const Real height = v->m_currentHeight;
		Real shudderX = GetGameLogicRandomValueReal(-d->m_maxShudder, d->m_maxShudder,
			const_cast<char *>(kRetailSourceFile), 228);
		shudderX += v->m_originX;
		Real shudderY = GetGameLogicRandomValueReal(-d->m_maxShudder, d->m_maxShudder,
			const_cast<char *>(kRetailSourceFile), 228);
		shudderY += v->m_originY;
		Coord3D position;
		position.x = shudderX;
		position.y = shudderY;
		position.z = height + v->m_originZ;
		building->setPosition(&position);

		if (now >= v->m_burstFrame)
		{
			if (GetGameLogicRandomValue(1, d->m_bigBurstFrequency,
				const_cast<char *>(kRetailSourceFile), 237) == 1)
			{
				module->doPhaseStuff(SCPHASE_BURST, &object->m_position);
			}
			else
			{
				module->doPhaseStuff(SCPHASE_DELAY, &object->m_position);
			}
			// This has to use a game logic random value since the bursts can spawn
			// debris, and debris is sync'd.
			v->m_burstFrame += GetGameLogicRandomValue(
				d->m_minBurstDelay, d->m_maxBurstDelay,
				const_cast<char *>(kRetailSourceFile), 246);
		}

		if ((base->getCollapseHeight() + v->m_currentHeight) <= 0.0f)
		{
			v->m_collapseState = COLLAPSESTATE_DONE;
			module->doPhaseStuff(SCPHASE_FINAL, &object->m_position);

			Drawable *drawable = building->getDrawable();
			reinterpret_cast<Rva002AE520StructureCollapseDone *>(base)->collapseDoneLookup();

			ModelConditionFlags cleared(
				ModelConditionFlags::kInit, 0x42, 0x43, 0x44, 5);
			reinterpret_cast<Object *>(building)->clearModelConditionFlags(cleared);
			if ((object->m_modelConditionFlags & 0x4000000u) == 0)
			{
				object->m_modelConditionFlags |= 0x4000000u;
				reinterpret_cast<Object *>(building)->notifyModelConditionChanged();
			}
			building->setOrientation(object->m_orientation);

			// Need to update body particle systems, now
			object->m_bodyModule->updateBodyParticleSystems();

			Matrix3D resetMatrix = *getDrawableInstanceMatrix(drawable);
			resetMatrix.m03 = 0.0f;
			resetMatrix.m13 = 0.0f;
			resetMatrix.m23 = 0.0f;
			drawable->setInstanceMatrix(&resetMatrix, true);

			return UPDATE_SLEEP_FOREVER;
		}

		if ((0.7f * (base->getCollapseHeight() + v->m_currentHeight) + v->m_currentHeight) <= 0.0f)
		{
			module->doPhaseStuff(SCPHASE_ALMOST_FINAL, &object->m_position);
			object->m_bodyModule->updateBodyParticleSystems();
		}
	}

	return (UpdateSleepTime)1;
}
